using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

namespace ZeroCue.DataProbe.Services.Drivers
{
    public enum InfOwnership
    {
        /// <summary>Not a WinUSB package for a ZeroCue-managed identity, or not recognisably ours.</summary>
        Foreign,

        /// <summary>WinUSB package generated by ZeroCue (libwdi with a ZeroCue device/source name).</summary>
        ZeroCue,

        /// <summary>Fingerprint of WinUSB packages produced by early ZeroCue builds ("SCUF" device name).</summary>
        LegacyZeroCue,

        /// <summary>Narrow fingerprint of a Zadig WinUSB package for a SCUF interface.</summary>
        ScopedZadig
    }

    public sealed record InfInfo(
        string? Provider,
        string? DeviceName,
        string? SourceName,
        string? VendorName,
        string? Class,
        string? CatalogFile,
        string? DriverVer,
        bool InstallsWinUsb,
        IReadOnlySet<string> HardwareKeys)
    {
        public bool IsLibWdi => string.Equals(Provider, "libwdi", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Parses the small subset of libwdi INF syntax needed to decide ownership.
    /// Hardware IDs are matched as exact tokens, so <c>PID_3A09</c> never matches
    /// <c>PID_3A09&amp;MI_00</c> and <c>MI_0</c> never matches <c>MI_03</c>.
    /// </summary>
    public static class InfClassifier
    {
        private static readonly Regex StringsEntry = new(
            @"^\s*(?<key>[A-Za-z][A-Za-z0-9_]*)\s*=\s*""(?<value>[^""]*)""\s*$",
            RegexOptions.Multiline | RegexOptions.CultureInvariant);

        private static readonly Regex PlainEntry = new(
            @"^\s*(?<key>[A-Za-z][A-Za-z0-9_]*)\s*=\s*(?<value>[^;\r\n]*?)\s*$",
            RegexOptions.Multiline | RegexOptions.CultureInvariant);

        // VID_xxxx&PID_xxxx with an optional &MI_xx, terminated by a non-identifier char.
        private static readonly Regex HardwareKeyToken = new(
            @"(?<![A-Za-z0-9_])VID_(?<vid>[0-9A-Fa-f]{4})&PID_(?<pid>[0-9A-Fa-f]{4})(?:&MI_(?<mi>[0-9A-Fa-f]{2}))?(?![A-Za-z0-9_&])",
            RegexOptions.CultureInvariant);

        private static readonly Regex WinUsbService = new(
            @"^\s*AddService\s*=\s*WinUSB\s*,",
            RegexOptions.Multiline | RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        public static InfInfo Parse(string content)
        {
            var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (Match match in StringsEntry.Matches(content))
            {
                values.TryAdd(match.Groups["key"].Value, match.Groups["value"].Value);
            }

            foreach (Match match in PlainEntry.Matches(content))
            {
                var value = match.Groups["value"].Value.Trim().Trim('"');
                values.TryAdd(match.Groups["key"].Value, value);
            }

            var hardwareKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Match match in HardwareKeyToken.Matches(content))
            {
                var key = $"VID_{match.Groups["vid"].Value.ToUpperInvariant()}&PID_{match.Groups["pid"].Value.ToUpperInvariant()}";
                if (match.Groups["mi"].Success)
                {
                    key += $"&MI_{match.Groups["mi"].Value.ToUpperInvariant()}";
                }

                hardwareKeys.Add(key);
            }

            return new InfInfo(
                Get(values, "Provider"),
                Get(values, "DeviceName"),
                Get(values, "SourceName"),
                Get(values, "VendorName"),
                Get(values, "Class"),
                Get(values, "CatalogFile"),
                Get(values, "DriverVer"),
                WinUsbService.IsMatch(content),
                hardwareKeys);
        }

        /// <summary>
        /// Classifies a package against the hardware keys ZeroCue manages. A package is
        /// only ever considered removable when it installs WinUSB, is a libwdi package
        /// and every hardware key it declares belongs to <paramref name="managedHardwareKeys"/>.
        /// </summary>
        public static InfOwnership Classify(InfInfo info, IEnumerable<string> managedHardwareKeys)
        {
            if (!info.InstallsWinUsb || !info.IsLibWdi || info.HardwareKeys.Count == 0)
            {
                return InfOwnership.Foreign;
            }

            var managed = new HashSet<string>(managedHardwareKeys, StringComparer.OrdinalIgnoreCase);
            if (!info.HardwareKeys.All(managed.Contains))
            {
                return InfOwnership.Foreign;
            }

            if (Contains(info.DeviceName, "ZeroCue") || Contains(info.SourceName, "ZeroCue"))
            {
                return InfOwnership.ZeroCue;
            }

            bool usbDeviceClass = string.Equals(info.Class, "USBDevice", StringComparison.OrdinalIgnoreCase);
            if (usbDeviceClass &&
                string.Equals(info.DeviceName, "SCUF", StringComparison.Ordinal) &&
                string.Equals(info.SourceName, "SCUF Install Disk", StringComparison.Ordinal) &&
                string.Equals(info.CatalogFile, "usb_device.cat", StringComparison.OrdinalIgnoreCase) &&
                NormalizeDriverVer(info.DriverVer) == "04/18/2019,6.1.7600.16385")
            {
                return InfOwnership.LegacyZeroCue;
            }

            if (usbDeviceClass &&
                info.DeviceName != null && info.DeviceName.StartsWith("SCUF", StringComparison.Ordinal) &&
                string.Equals(info.VendorName, "Corsair", StringComparison.Ordinal) &&
                info.SourceName != null && info.SourceName.StartsWith("SCUF", StringComparison.Ordinal) &&
                info.SourceName.EndsWith(" Install Disk", StringComparison.Ordinal) &&
                NormalizeDriverVer(info.DriverVer) == "06/02/2012,6.1.7600.16385")
            {
                return InfOwnership.ScopedZadig;
            }

            return InfOwnership.Foreign;
        }

        public static bool IsPublishedInfName(string? value) =>
            value != null && Regex.IsMatch(value, @"^oem[0-9]{1,5}\.inf$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        private static string? Get(Dictionary<string, string> values, string key) =>
            values.TryGetValue(key, out var value) && !string.IsNullOrWhiteSpace(value) ? value : null;

        private static bool Contains(string? value, string marker) =>
            value != null && value.Contains(marker, StringComparison.OrdinalIgnoreCase);

        private static string? NormalizeDriverVer(string? value) =>
            value == null ? null : Regex.Replace(value, @"\s+", string.Empty);
    }
}
